drills.solution:
export function sortBy(rows, spec) {
  const keys = spec
    .split(',')
    .map((k) => k.trim())
    .filter(Boolean)
    .map((k) => (k.startsWith('-') ? { key: k.slice(1), dir: -1 } : { key: k, dir: 1 }));
  return rows.toSorted((a, b) => {
    for (const { key, dir } of keys) {
      if (a[key] < b[key]) return -dir;
      if (a[key] > b[key]) return dir;
    }
    return 0;
  });
}

